"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";

type Currency = { id: string; code: string };
type Provider = { id: string; name: string; websiteUrl?: string | null };
type Account = { id: string; name: string; accountType: string; provider: Provider; currency: Currency; accountNumberMasked?: string | null; note?: string | null; isActive?: boolean; cashAccount?: { id: string; balance: string | number } | null };
type Asset = { id: string; symbol?: string | null; name: string; assetType: string; unitName: string; currency: Currency };
type Sale = { id: string; date: string; quantity: string | number; price: string | number; proceeds: string | number; realized: string | number };
type LotRow = { id: string; lotId: string; transactionDate: string; asset: Asset; quantity: string | number; soldQuantity: string | number; remainingQuantity: string | number; unitPrice: string | number; totalCost: string | number; minimumSellPrice: string | number; currentPrice: string | number | null; priceAsOf: string | null; currentValue: string | number; unrealizedGainLoss: string | number; sales: Sale[] };
type Ledger = { account: Account; rows: LotRow[]; summary: { openLots: number; openQuantity: string | number; realizedGainLoss: string | number } };
type Holding = { id: string; quantity: string | number; costBasis: string | number; currentPrice?: string | number | null; marketValue: string | number; gain: string | number; returnPct: string | number; asset: Asset; account: Account };
type Cash = { id: string; balance: string | number; account: Account };
type Overview = { currencies: Currency[]; providers: Provider[]; accounts: Account[]; assets: Asset[]; holdings: Holding[]; cashAccounts: Cash[]; summary: { totalValue: string | number; totalCash: string | number; totalInvestmentValue: string | number; unrealized: string | number; returnPct: string | number } };
type RdnHistoryRow = { id: string; date: string; description: string; debit: string | number; credit: string | number; balance: string | number; movementType: string };
type AssetSummary = { asset: Asset; quantity: number; cost: number; avgCost: number; currentPrice: number | null; marketValue: number; sellFee: number; netValue: number; pnl: number; minSell: number; rows: LotRow[] };
type AccountForm = { providerName: string; websiteUrl: string; rdnBankName: string; rdnAccountNumber: string; buyFeePct: string; sellFeePct: string; currencyId: string };
type Trade = { type: "BUY" | "SELL"; assetId: string; assetQuery: string; quantity: string; unitPrice: string; tax: string; other: string; date: string; sourceLotId: string; fundingCashAccountId: string };

const input = "w-full rounded-xl border border-white/10 bg-[#080f17] px-3 py-2.5 text-sm text-white outline-none placeholder:text-slate-600";
const select = `${input} text-slate-300`;
const card = "rounded-2xl border border-white/10 bg-[#0d151e] p-5";
const today = () => new Date().toISOString().slice(0, 10);
const nf = (value: string | number | null | undefined, digits = 2) => { const x = Number(value ?? 0); return Number.isFinite(x) ? new Intl.NumberFormat("id-ID", { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(x) : "0"; };
const cp = (code: string) => ({ IDR: "Rp", USD: "US$", SGD: "S$", MYR: "RM", JPY: "¥", EUR: "€", GBP: "£" } as Record<string, string>)[code] ?? code;
const money = (value: string | number | null | undefined, code = "IDR") => `${cp(code)}${nf(value)}`;
const feeInfo = (a: Account) => { try { const p = a.note ? JSON.parse(a.note) as Record<string, unknown> : {}; return { buyFeePct: Number(p.buyFeePct ?? 0) || 0, sellFeePct: Number(p.sellFeePct ?? 0) || 0, rdnBankName: String(p.rdnBankName ?? ""), rdnAccountNumber: String(p.rdnAccountNumber ?? "") }; } catch { return { buyFeePct: 0, sellFeePct: 0, rdnBankName: "", rdnAccountNumber: "" }; } };
const unitsPerLot = (a?: Asset) => a?.assetType === "STOCK" ? 100 : 1;
const assetLabel = (a: Asset) => a.symbol ? `${a.symbol} · ${a.name}` : a.name;

async function getOverview(): Promise<Overview> { const r = await fetch("/api/investments", { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load investments."); return j; }
async function postV2(body: Record<string, unknown>) { const r = await fetch("/api/investments/v2", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Investment operation failed."); return j; }
async function postV4(body: Record<string, unknown>) { const r = await fetch("/api/investments/v4", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Investment operation failed."); return j; }

function AssetPicker({ assets, value, selectedId, onChange, onSelect }: { assets: Asset[]; value: string; selectedId: string; onChange: (v: string) => void; onSelect: (a: Asset) => void }) {
  const [open, setOpen] = useState(false);
  const q = value.trim().toLowerCase();
  const filtered = useMemo(() => assets.filter(a => !q || assetLabel(a).toLowerCase().includes(q) || String(a.symbol ?? "").toLowerCase() === q || a.name.toLowerCase().includes(q)).slice(0, 12), [assets, q]);
  const hasExact = filtered.some(a => String(a.symbol ?? "").toLowerCase() === q || assetLabel(a).toLowerCase() === q);
  return <div className="relative">
    <input className={`${input} ${selectedId ? "border-emerald-400/40" : ""}`} placeholder="Asset / Stock (type to search)" value={value} autoComplete="off" onFocus={() => setOpen(true)} onChange={e => { const next = e.target.value; onChange(next); setOpen(true); const exact = assets.find(a => String(a.symbol ?? "").toLowerCase() === next.trim().toLowerCase() || assetLabel(a).toLowerCase() === next.trim().toLowerCase()); if (exact) onSelect(exact); }} />
    {open && filtered.length > 0 && <div className="absolute left-0 right-0 top-full z-[120] mt-1 max-h-52 overflow-y-auto rounded-xl border border-white/10 bg-[#0b121a] p-1 shadow-2xl">{filtered.map(a => <button key={a.id} type="button" onMouseDown={e => e.preventDefault()} onClick={() => { onSelect(a); setOpen(false); }} className="flex w-full items-center justify-between rounded-lg px-3 py-2 text-left hover:bg-white/[.05]"><span><span className="block text-sm font-semibold text-white">{a.symbol || a.name}</span><span className="block text-[10px] text-slate-500">{a.name}</span></span><span className="text-[9px] uppercase text-slate-600">{a.assetType}</span></button>)}</div>}
    {open && q && filtered.length === 0 && <div className="mt-1 rounded-xl border border-emerald-400/20 bg-emerald-400/[.04] px-3 py-2 text-xs text-emerald-300">Kode “{value.trim().toUpperCase()}” akan dibuat otomatis saat BUY disimpan.</div>}
    {open && q && filtered.length > 0 && !hasExact && <div className="mt-1 text-[10px] text-emerald-300">Kode baru akan dibuat otomatis jika belum ada.</div>}
  </div>;
}

function AccountModal({ open, editing, form, currencies, onClose, onChange, onSubmit, busy }: { open: boolean; editing: Account | null; form: AccountForm; currencies: Currency[]; onClose: () => void; onChange: (f: AccountForm) => void; onSubmit: (e: FormEvent) => void; busy: boolean }) {
  if (!open) return null;
  return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><form onSubmit={onSubmit} className="w-full max-w-2xl rounded-3xl border border-white/10 bg-[#0b121a] p-6 shadow-2xl"><div className="mb-6 flex items-start justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[.18em] text-emerald-400">Investments</p><h2 className="mt-1 text-2xl font-bold text-white">{editing ? "Edit Investment Account" : "Add Investment Account"}</h2><p className="mt-1 text-xs text-slate-500">Buat sekali, lalu account akan selalu tersedia di OKANE.</p></div><button type="button" onClick={onClose} className="text-2xl text-slate-500 hover:text-white">×</button></div><div className="grid gap-4 md:grid-cols-2"><label className="text-xs text-slate-500">Investment account / broker<input className={`${input} mt-2`} value={form.providerName} onChange={e => onChange({ ...form, providerName: e.target.value })} placeholder="contoh: IndoPremier" required /></label><label className="text-xs text-slate-500">Website <span className="text-slate-700">(optional)</span><input className={`${input} mt-2`} value={form.websiteUrl} onChange={e => onChange({ ...form, websiteUrl: e.target.value })} placeholder="https://..." /></label><label className="text-xs text-slate-500">RDN Bank<input className={`${input} mt-2`} value={form.rdnBankName} onChange={e => onChange({ ...form, rdnBankName: e.target.value })} placeholder="contoh: BCA" /></label><label className="text-xs text-slate-500">RDN Account Number<input className={`${input} mt-2`} value={form.rdnAccountNumber} onChange={e => onChange({ ...form, rdnAccountNumber: e.target.value })} placeholder="Nomor RDN" /></label><label className="text-xs text-slate-500">Currency<select className={`${select} mt-2`} value={form.currencyId} onChange={e => onChange({ ...form, currencyId: e.target.value })}>{currencies.map(c => <option key={c.id} value={c.id}>{c.code}</option>)}</select></label><div /><label className="text-xs text-slate-500">Buy fee %<input className={`${input} mt-2`} type="number" min="0" step="0.001" value={form.buyFeePct} onChange={e => onChange({ ...form, buyFeePct: e.target.value })} /></label><label className="text-xs text-slate-500">Sell fee %<input className={`${input} mt-2`} type="number" min="0" step="0.001" value={form.sellFeePct} onChange={e => onChange({ ...form, sellFeePct: e.target.value })} /></label></div><div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-xl border border-white/10 px-4 py-2.5 text-sm text-slate-300">Cancel</button><button type="submit" disabled={busy} className="rounded-xl bg-emerald-400 px-5 py-2.5 text-sm font-bold text-[#07110b] disabled:opacity-50">{busy ? "Saving…" : editing ? "Save changes" : "Create account"}</button></div></form></div>;
}

function TradeModal({ open, trade, assets, account, ledger, onClose, onChange, onSubmit, busy }: { open: boolean; trade: Trade; assets: Asset[]; account: Account; ledger: Ledger | null; onClose: () => void; onChange: (t: Trade) => void; onSubmit: (e: FormEvent) => void; busy: boolean }) {
  const selectedAsset = assets.find(a => a.id === trade.assetId) ?? assets.find(a => assetLabel(a).toLowerCase() === trade.assetQuery.trim().toLowerCase());
  const lots = (ledger?.rows ?? []).filter(r => r.asset.id === trade.assetId && Number(r.remainingQuantity) > 0);
  const feePct = trade.type === "BUY" ? feeInfo(account).buyFeePct : feeInfo(account).sellFeePct;
  const units = unitsPerLot(selectedAsset);
  const gross = Number(trade.quantity || 0) * units * Number(trade.unitPrice || 0);
  const fee = gross * feePct / 100;
  const tax = Number(trade.tax || 0); const other = Number(trade.other || 0);
  const cash = trade.type === "BUY" ? gross + fee + tax + other : gross - fee - tax - other;
  const sellLot = trade.sourceLotId ? lots.find(r => r.lotId === trade.sourceLotId) : undefined;
  const qtyUnits = Number(trade.quantity || 0) * units;
  const quantityValid = trade.type !== "SELL" || (!!sellLot && qtyUnits <= Number(sellLot.remainingQuantity));
  const canSubmit = !!trade.assetQuery.trim() && Number(trade.quantity) > 0 && Number(trade.unitPrice) > 0 && !!trade.fundingCashAccountId && (trade.type === "BUY" || (!!trade.sourceLotId && quantityValid));
  const sellPnl = trade.type === "SELL" && sellLot && quantityValid ? (gross - fee - tax - other) - (Number(sellLot.totalCost) * qtyUnits / Math.max(Number(sellLot.quantity), 1)) : null;
  if (!open) return null;
  return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><form onSubmit={onSubmit} className="w-full max-w-4xl max-h-[90vh] overflow-y-auto rounded-3xl border border-white/10 bg-[#0b121a] p-6 shadow-2xl"><div className="mb-5 flex items-start justify-between"><div><p className="text-[10px] uppercase tracking-[.18em] text-emerald-400">{account.provider.name}</p><h2 className="mt-1 text-2xl font-bold text-white">New {trade.type === "BUY" ? "Buy" : "Sell"} Transaction</h2></div><button type="button" onClick={onClose} className="text-2xl text-slate-500 hover:text-white">×</button></div><div className="mb-5 grid grid-cols-2 rounded-2xl border border-white/10 bg-[#080f17] p-1"><button type="button" onClick={() => onChange({ ...trade, type: "BUY", sourceLotId: "" })} className={`rounded-xl py-3 text-lg font-bold ${trade.type === "BUY" ? "bg-emerald-400 text-[#07110b]" : "text-slate-500"}`}>BUY</button><button type="button" onClick={() => onChange({ ...trade, type: "SELL", sourceLotId: "" })} className={`rounded-xl py-3 text-lg font-bold ${trade.type === "SELL" ? "bg-emerald-400 text-[#07110b]" : "text-slate-500"}`}>SELL</button></div><div className="grid gap-4 md:grid-cols-2"><label className="text-xs text-slate-500">Asset / Stock<AssetPicker assets={assets} value={trade.assetQuery} selectedId={trade.assetId} onChange={v => onChange({ ...trade, assetQuery: v, assetId: assets.find(a => assetLabel(a).toLowerCase() === v.trim().toLowerCase() || String(a.symbol ?? "").toLowerCase() === v.trim().toLowerCase())?.id ?? "" })} onSelect={a => onChange({ ...trade, assetId: a.id, assetQuery: assetLabel(a), sourceLotId: "" })} /></label><label className="text-xs text-slate-500">Date<input className={`${input} mt-2`} type="date" value={trade.date} onChange={e => onChange({ ...trade, date: e.target.value })} /></label><label className="text-xs text-slate-500">Quantity {selectedAsset?.assetType === "STOCK" ? "(lots)" : `(${selectedAsset?.unitName || "units"})`}<input className={`${input} mt-2`} type="number" min="0.0001" step="0.0001" value={trade.quantity} onChange={e => onChange({ ...trade, quantity: e.target.value })} placeholder="1" />{trade.type === "SELL" && sellLot && !quantityValid && <span className="mt-1 block text-[10px] text-red-300">Maksimum {nf(Number(sellLot.remainingQuantity) / units)} {selectedAsset?.assetType === "STOCK" ? "lot" : "unit"} untuk lot ini.</span>}</label><label className="text-xs text-slate-500">Price / unit<input className={`${input} mt-2`} type="number" min="0.01" step="0.01" value={trade.unitPrice} onChange={e => onChange({ ...trade, unitPrice: e.target.value })} placeholder="3150" /></label></div>{trade.type === "SELL" && selectedAsset && lots.length > 0 && <label className="mt-4 block text-xs text-slate-500">Purchase lot to sell<select className={`${select} mt-2`} value={trade.sourceLotId} onChange={e => onChange({ ...trade, sourceLotId: e.target.value })}><option value="">Select purchase lot</option>{lots.map(r => <option key={r.lotId} value={r.lotId}>{new Date(r.transactionDate).toLocaleDateString("id-ID")} · {r.symbol ?? r.asset.symbol ?? r.asset.name} · remaining {nf(Number(r.remainingQuantity) / unitsPerLot(r.asset))}</option>)}</select></label>}
    <div className="mt-4 grid gap-4 md:grid-cols-3"><div className="rounded-2xl border border-emerald-400/20 bg-emerald-400/[.04] p-4"><p className="text-[10px] uppercase tracking-widest text-slate-500">Auto fee · {nf(feePct, 3)}%</p><p className="mt-2 text-xl font-bold text-emerald-300">{money(fee, account.currency.code)}</p></div><div className="rounded-2xl border border-white/10 bg-white/[.02] p-4"><p className="text-[10px] uppercase tracking-widest text-slate-500">{trade.type === "BUY" ? "Cash required" : "Net proceeds"}</p><p className="mt-2 text-xl font-bold text-white">{money(cash, account.currency.code)}</p></div>{trade.type === "SELL" && <div className={`rounded-2xl border p-4 ${sellPnl != null && sellPnl >= 0 ? "border-emerald-400/20 bg-emerald-400/[.04]" : "border-red-400/20 bg-red-400/[.04]"}`}><p className="text-[10px] uppercase tracking-widest text-slate-500">Estimated P/L</p><p className={`mt-2 text-xl font-bold ${sellPnl != null && sellPnl >= 0 ? "text-emerald-300" : "text-red-300"}`}>{sellPnl == null ? "—" : money(sellPnl, account.currency.code)}</p></div>}</div>
    <div className="mt-4 rounded-2xl border border-white/10 bg-[#0d151e] p-4"><button type="button" className="text-sm font-semibold text-slate-300" onClick={e => { const el = e.currentTarget.nextElementSibling as HTMLElement | null; if (el) el.hidden = !el.hidden; }}>Tax / Other</button><div className="mt-3 grid gap-4 md:grid-cols-2"><label className="text-xs text-slate-500">Tax<input className={`${input} mt-2`} type="number" min="0" step="0.01" value={trade.tax} onChange={e => onChange({ ...trade, tax: e.target.value })} /></label><label className="text-xs text-slate-500">Other charges<input className={`${input} mt-2`} type="number" min="0" step="0.01" value={trade.other} onChange={e => onChange({ ...trade, other: e.target.value })} /></label></div></div>
    <div className="mt-5"><label className="text-xs text-slate-500">Settlement RDN<select className={`${select} mt-2`} value={trade.fundingCashAccountId} onChange={e => onChange({ ...trade, fundingCashAccountId: e.target.value })}><option value="">Select RDN</option>{(account.cashAccount ? [account.cashAccount.id] : []).map(id => <option key={id} value={id}>{account.provider.name} · {feeInfo(account).rdnBankName || "RDN"} · {money(account.cashAccount?.balance ?? 0, account.currency.code)}</option>)}</select></label></div>
    <div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-xl border border-white/10 px-4 py-3 text-sm text-slate-300">Cancel</button><button type="submit" disabled={!canSubmit || busy} className="rounded-xl bg-emerald-400 px-5 py-3 text-sm font-bold text-[#07110b] disabled:cursor-not-allowed disabled:opacity-40">{busy ? "Saving…" : "Save transaction"}</button></div></form></div>;
}

function SellAllModal({ open, summary, account, price, setPrice, onClose, onSubmit, busy }: { open: boolean; summary: AssetSummary | null; account: Account | null; price: string; setPrice: (v: string) => void; onClose: () => void; onSubmit: () => void; busy: boolean }) {
  if (!open || !summary || !account) return null;
  const f = feeInfo(account); const current = summary.currentPrice ?? 0; const breakeven = summary.minSell;
  const previewPrice = Number(price || 0); const totalGross = summary.quantity * unitsPerLot(summary.asset) * previewPrice; const sellFee = totalGross * f.sellFeePct / 100; const net = totalGross - sellFee; const pnl = net - summary.cost;
  return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><div className="w-full max-w-2xl rounded-3xl border border-white/10 bg-[#0b121a] p-6 shadow-2xl"><div className="mb-5 flex items-start justify-between"><div><p className="text-[10px] uppercase tracking-[.18em] text-emerald-400">SELL ALL</p><h2 className="mt-1 text-2xl font-bold text-white">{summary.asset.symbol || summary.asset.name}</h2><p className="mt-1 text-xs text-slate-500">{nf(summary.quantity / unitsPerLot(summary.asset), 0)} lot · {nf(summary.quantity, 0)} shares</p></div><button type="button" onClick={onClose} className="text-2xl text-slate-500">×</button></div><div className="grid grid-cols-3 gap-2"><button type="button" onClick={() => setPrice(String(current))} className="rounded-xl border border-white/10 bg-white/[.03] px-3 py-3 text-left"><span className="block text-[10px] text-slate-600">Current</span><span className="mt-1 block font-semibold text-white">{money(current, account.currency.code)}</span></button><button type="button" onClick={() => setPrice(String(breakeven))} className="rounded-xl border border-amber-400/20 bg-amber-400/[.04] px-3 py-3 text-left"><span className="block text-[10px] text-slate-600">Break-even</span><span className="mt-1 block font-semibold text-amber-300">{money(breakeven, account.currency.code)}</span></button><div className="rounded-xl border border-white/10 bg-white/[.03] px-3 py-3"><span className="block text-[10px] text-slate-600">Sell price</span><input className="mt-1 w-full bg-transparent text-sm font-semibold text-white outline-none" type="number" min="0.01" step="0.01" value={price} onChange={e => setPrice(e.target.value)} /></div></div><div className="mt-4 grid gap-3 md:grid-cols-3"><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] text-slate-600">Gross</p><p className="mt-1 font-semibold text-white">{money(totalGross, account.currency.code)}</p></div><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] text-slate-600">Sell fee</p><p className="mt-1 font-semibold text-white">{money(sellFee, account.currency.code)}</p></div><div className={`rounded-xl border p-4 ${pnl >= 0 ? "border-emerald-400/20 bg-emerald-400/[.04]" : "border-red-400/20 bg-red-400/[.04]"}`}><p className="text-[10px] text-slate-600">Estimated P/L</p><p className={`mt-1 font-semibold ${pnl >= 0 ? "text-emerald-300" : "text-red-300"}`}>{money(pnl, account.currency.code)}</p></div></div><div className="mt-5 space-y-2 rounded-2xl border border-white/10 bg-white/[.02] p-4">{summary.rows.map(r => <div key={r.lotId} className="flex items-center justify-between text-xs"><span className="text-slate-400">{new Date(r.transactionDate).toLocaleDateString("id-ID")} · {nf(Number(r.remainingQuantity) / unitsPerLot(r.asset), 0)} lot @ {money(r.unitPrice, account.currency.code)}</span><span className="text-slate-200">P/L {money((Number(r.remainingQuantity) * previewPrice - Number(r.remainingQuantity) * previewPrice * f.sellFeePct / 100) - (Number(r.totalCost) * Number(r.remainingQuantity) / Math.max(Number(r.quantity), 1)), account.currency.code)}</span></div>)}</div><div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-xl border border-white/10 px-4 py-3 text-sm text-slate-300">Cancel</button><button type="button" disabled={busy || previewPrice <= 0} onClick={onSubmit} className="rounded-xl bg-emerald-400 px-5 py-3 text-sm font-bold text-[#07110b] disabled:opacity-40">{busy ? "Processing…" : "Confirm Sell All"}</button></div></div></div>;
}

export default function InvestmentDashboardV5() {
  const [data, setData] = useState<Overview | null>(null);
  const [screen, setScreen] = useState<"overview" | "transactions" | "accounts">("overview");
  const [accountId, setAccountId] = useState("");
  const [ledger, setLedger] = useState<Ledger | null>(null);
  const [selectedAssetId, setSelectedAssetId] = useState("");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [showTrade, setShowTrade] = useState(false);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editing, setEditing] = useState<Account | null>(null);
  const [accountForm, setAccountForm] = useState<AccountForm>({ providerName: "", websiteUrl: "", rdnBankName: "", rdnAccountNumber: "", buyFeePct: "", sellFeePct: "", currencyId: "" });
  const [showSellAll, setShowSellAll] = useState(false);
  const [sellAllAssetId, setSellAllAssetId] = useState("");
  const [sellAllPrice, setSellAllPrice] = useState("");
  const [trade, setTrade] = useState<Trade>({ type: "BUY", assetId: "", assetQuery: "", quantity: "", unitPrice: "", tax: "0", other: "0", date: today(), sourceLotId: "", fundingCashAccountId: "" });
  const [historyRows, setHistoryRows] = useState<RdnHistoryRow[]>([]);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [cashBalance, setCashBalance] = useState("");
  const [cashDate, setCashDate] = useState(today());
  const [withdrawWallets, setWithdrawWallets] = useState<Array<{ id: string; name: string; balance: number; currency: Currency }>>([]);
  const [withdrawWalletId, setWithdrawWalletId] = useState("");
  const [withdrawAmount, setWithdrawAmount] = useState("");
  const [importing, setImporting] = useState(false);

  const reload = async () => setData(await getOverview());
  const loadLedger = async (id: string) => { const r = await fetch(`/api/investments/v2?accountId=${encodeURIComponent(id)}`, { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load transactions."); setLedger(j); };
  const loadHistory = async (cashId: string) => { if (!cashId) return; setHistoryLoading(true); try { const r = await fetch(`/api/investments/cash-transfer?cashAccountId=${encodeURIComponent(cashId)}`, { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load RDN history."); setHistoryRows(j.rows ?? []); } finally { setHistoryLoading(false); } };
  const loadWallets = async () => { const r = await fetch("/api/investments/cash-transfer", { cache: "no-store" }); const j = await r.json(); if (r.ok) setWithdrawWallets(j.wallets ?? []); };

  useEffect(() => { reload().catch(e => setMessage(e instanceof Error ? e.message : "Unable to load investments.")); loadWallets().catch(() => undefined); }, []);
  useEffect(() => { if (accountId) loadLedger(accountId).catch(e => setMessage(e instanceof Error ? e.message : "Unable to load transactions.")); else setLedger(null); }, [accountId]);
  useEffect(() => { if (screen === "transactions" && !accountId && accounts.length) setAccountId(accounts[0].id); }, [screen]);
  const accounts = data?.accounts ?? [];
  useEffect(() => { if (screen === "accounts") { setAccountId(""); setLedger(null); setSelectedAssetId(""); } }, [screen]);

  const currencies = data?.currencies ?? [];
  const assets = data?.assets ?? [];
  const holdings = data?.holdings ?? [];
  const selected = accounts.find(a => a.id === accountId) ?? null;
  const selectedCash = selected?.cashAccount ? (data?.cashAccounts ?? []).find(c => c.id === selected.cashAccount?.id) ?? null : null;
  const fee = selected ? feeInfo(selected) : { buyFeePct: 0, sellFeePct: 0, rdnBankName: "", rdnAccountNumber: "" };
  const transactionAssets = useMemo(() => { const seen = new Set<string>(); const out: Asset[] = []; for (const row of ledger?.rows ?? []) if (!seen.has(row.asset.id)) { seen.add(row.asset.id); out.push(row.asset); } return out; }, [ledger]);
  const pickerAssets = useMemo(() => { const seen = new Set<string>(); return [...transactionAssets, ...assets].filter(a => !seen.has(a.id) && seen.add(a.id)); }, [transactionAssets, assets]);
  const assetSummaries = useMemo<AssetSummary[]>(() => { if (!ledger || !selected) return []; const sellFeePct = feeInfo(selected).sellFeePct; const groups = new Map<string, LotRow[]>(); for (const row of ledger.rows) { const rem = Number(row.remainingQuantity); if (rem <= 0) continue; const list = groups.get(row.asset.id) ?? []; list.push(row); groups.set(row.asset.id, list); } return [...groups.values()].map(rows => { const asset = rows[0].asset; const units = unitsPerLot(asset); const quantity = rows.reduce((s, r) => s + Number(r.remainingQuantity), 0); const cost = rows.reduce((s, r) => s + Number(r.totalCost) * Number(r.remainingQuantity) / Math.max(Number(r.quantity), 1), 0); const avgCost = quantity > 0 ? cost / quantity : 0; const p = rows.find(r => r.currentPrice != null)?.currentPrice; const currentPrice = p == null ? null : Number(p); const marketValue = currentPrice == null ? 0 : quantity * currentPrice; const sellFee = marketValue * sellFeePct / 100; const netValue = marketValue - sellFee; const pnl = netValue - cost; const minSell = quantity > 0 && sellFeePct < 100 ? (cost / quantity) / (1 - sellFeePct / 100) : 0; return { asset, quantity, cost, avgCost, currentPrice, marketValue, sellFee, netValue, pnl, minSell, rows }; }).sort((a, b) => b.marketValue - a.marketValue); }, [ledger, selected]);
  const selectedSummary = assetSummaries.find(x => x.asset.id === selectedAssetId) ?? null;
  const openRows = useMemo(() => [...(ledger?.rows ?? [])].filter(r => Number(r.remainingQuantity) > 0).sort((a, b) => new Date(b.transactionDate).getTime() - new Date(a.transactionDate).getTime()), [ledger]);
  const closedSales = useMemo(() => (ledger?.rows ?? []).flatMap(r => r.sales.map(s => ({ lot: r, sale: s }))).sort((a, b) => new Date(b.sale.date).getTime() - new Date(a.sale.date).getTime()), [ledger]);

  function chooseAccount(id: string, destination: "transactions" | "accounts" = "accounts") { setAccountId(id); setSelectedAssetId(""); setScreen(destination); }
  function openAccountEditor(account?: Account) { setEditing(account ?? null); setAccountForm(account ? { providerName: account.provider.name, websiteUrl: account.provider.websiteUrl ?? "", rdnBankName: feeInfo(account).rdnBankName, rdnAccountNumber: feeInfo(account).rdnAccountNumber, buyFeePct: String(feeInfo(account).buyFeePct), sellFeePct: String(feeInfo(account).sellFeePct), currencyId: account.currency.id } : { providerName: "", websiteUrl: "", rdnBankName: "", rdnAccountNumber: "", buyFeePct: "", sellFeePct: "", currencyId: currencies[0]?.id ?? "" }); setShowAccountModal(true); }
  async function run(body: Record<string, unknown>, success: string, route: "v2" | "v4" = "v2") { setBusy(true); setMessage(""); try { if (route === "v4") await postV4(body); else await postV2(body); await reload(); if (accountId) await loadLedger(accountId); setMessage(success); return true; } catch (e) { setMessage(e instanceof Error ? e.message : "Operation failed."); return false; } finally { setBusy(false); } }
  function openTrade(type: "BUY" | "SELL", row?: LotRow) { setTrade({ type, assetId: row?.asset.id ?? selectedSummary?.asset.id ?? "", assetQuery: row ? assetLabel(row.asset) : selectedSummary ? assetLabel(selectedSummary.asset) : "", quantity: "", unitPrice: row?.currentPrice ? String(row.currentPrice) : selectedSummary?.currentPrice ? String(selectedSummary.currentPrice) : "", tax: "0", other: "0", date: today(), sourceLotId: row?.lotId ?? "", fundingCashAccountId: selected?.cashAccount?.id ?? "" }); setShowTrade(true); }
  async function submitTrade(e: FormEvent) { e.preventDefault(); if (!selected) return; let asset = pickerAssets.find(a => a.id === trade.assetId) ?? pickerAssets.find(a => assetLabel(a).toLowerCase() === trade.assetQuery.trim().toLowerCase()); if (!asset && trade.type === "BUY") { const symbol = trade.assetQuery.trim().toUpperCase(); if (!symbol) return setMessage("Enter an asset / stock first."); try { asset = await postV2({ action: "asset.resolve", accountId: selected.id, symbol, name: symbol, currencyId: selected.currency.id, assetType: "STOCK", unitName: "share" }); } catch (e) { return setMessage(e instanceof Error ? e.message : "Unable to create asset."); } } if (!asset || !trade.quantity || !trade.unitPrice || !trade.fundingCashAccountId) return setMessage("Lengkapi asset, quantity, harga dan RDN."); const units = unitsPerLot(asset); const qtyUnits = Number(trade.quantity) * units; if (trade.type === "SELL") { const row = ledger?.rows.find(r => r.lotId === trade.sourceLotId); if (!row || qtyUnits > Number(row.remainingQuantity)) return setMessage("Jumlah jual melebihi remaining lot."); } const gross = qtyUnits * Number(trade.unitPrice); const autoFee = gross * (trade.type === "BUY" ? fee.buyFeePct : fee.sellFeePct) / 100; const ok = await run({ action: "transaction.create", accountId: selected.id, assetId: asset.id, transactionType: trade.type, transactionDate: new Date(trade.date).toISOString(), quantity: qtyUnits, unitPrice: Number(trade.unitPrice), feeAmount: autoFee, taxAmount: Number(trade.tax || 0), otherCharges: Number(trade.other || 0), fundingCashAccountId: trade.fundingCashAccountId, sourceLotId: trade.sourceLotId || undefined }, "Transaction saved."); if (ok) setShowTrade(false); }
  async function saveAccount(e: FormEvent) { e.preventDefault(); const ok = await run(editing ? { action: "account.update", accountId: editing.id, ...accountForm, buyFeePct: Number(accountForm.buyFeePct || 0), sellFeePct: Number(accountForm.sellFeePct || 0) } : { action: "account.create", ...accountForm, buyFeePct: Number(accountForm.buyFeePct || 0), sellFeePct: Number(accountForm.sellFeePct || 0) }, editing ? "Account updated." : "Account created.", "v2"); if (ok) setShowAccountModal(false); }
  async function accountAction(action: "account.close" | "account.delete", account: Account) { const label = action.endsWith("close") ? "close" : "delete"; if (!window.confirm(`Yakin ingin ${label} ${account.provider.name}?`)) return; const ok = await run({ action, accountId: account.id }, action === "account.close" ? "Account closed." : "Account deleted.", "v2"); if (ok) setAccountId(""); }
  async function saveCash() { if (!selectedCash) return; const ok = await run({ action: "cash.setBalance", cashAccountId: selectedCash.id, balance: Number(cashBalance), date: new Date(cashDate).toISOString() }, "RDN balance updated."); if (ok) { setHistoryOpen(true); await loadHistory(selectedCash.id); } }
  async function withdraw() { const value = Number(withdrawAmount); if (!selectedCash || !withdrawWalletId || !Number.isFinite(value) || value <= 0 || value > Number(selectedCash.balance)) return setMessage("Nominal withdraw tidak valid."); setBusy(true); setMessage(""); try { const r = await fetch("/api/investments/cash-transfer", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ direction: "WITHDRAW", cashAccountId: selectedCash.id, walletId: withdrawWalletId, amount: value, date: new Date().toISOString() }) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Withdrawal failed."); await reload(); setWithdrawAmount(""); setHistoryOpen(true); await loadHistory(selectedCash.id); setMessage("Dana berhasil dipindahkan ke Wallet."); } catch (e) { setMessage(e instanceof Error ? e.message : "Withdrawal failed."); } finally { setBusy(false); } }
  async function importExcel(file: File) { if (!selected) return; setImporting(true); try { const form = new FormData(); form.append("action", "import.excel"); form.append("accountId", selected.id); form.append("file", file); const r = await fetch("/api/investments/v2", { method: "POST", body: form }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Import failed."); await reload(); await loadLedger(selected.id); setMessage(`Imported ${j.imported} rows. Skipped ${j.skipped}.`); } catch (e) { setMessage(e instanceof Error ? e.message : "Import failed."); } finally { setImporting(false); } }
  async function deleteTransaction(id: string) { if (!window.confirm("Hapus transaksi BUY ini?")) return; await run({ action: "transaction.delete", transactionId: id }, "Transaction deleted."); }
  async function sellAll() { if (!selected || !selectedSummary || !sellAllPrice) return; const ok = await run({ action: "transaction.sellAll", accountId: selected.id, assetId: selectedSummary.asset.id, transactionDate: new Date(today()).toISOString(), unitPrice: Number(sellAllPrice), fundingCashAccountId: selected.cashAccount?.id ?? "" }, "Sell All completed.", "v4"); if (ok) { setShowSellAll(false); setSellAllPrice(""); } }

  const activeAccounts = accounts.filter(a => a.isActive !== false);
  const selectedAssetRows = selectedAssetId ? openRows.filter(r => r.asset.id === selectedAssetId) : openRows;
  const selectedClosed = selectedAssetId ? closedSales.filter(x => x.lot.asset.id === selectedAssetId) : closedSales;

  return <div className="mx-auto w-full min-w-0 max-w-[1450px] px-5 py-8 lg:px-8"><header className="mb-6 flex w-full flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[.18em] text-emerald-400">Portfolio</p><h1 className="mt-1 text-3xl font-bold text-white">Investments</h1><p className="mt-2 text-sm text-slate-500">Accounts, holdings, transactions, RDN cash and performance.</p></div><nav className="flex flex-wrap gap-1 rounded-xl border border-white/10 bg-[#0b121a] p-1"><button onClick={() => { setScreen("overview"); setAccountId(""); }} className={`rounded-lg px-4 py-2 text-xs font-bold uppercase ${screen === "overview" ? "bg-white/[.09] text-white" : "text-slate-500"}`}>Overview</button><button onClick={() => setScreen("transactions")} className={`rounded-lg px-4 py-2 text-xs font-bold uppercase ${screen === "transactions" ? "bg-white/[.09] text-white" : "text-slate-500"}`}>Transactions</button><button onClick={() => setScreen("accounts")} className={`rounded-lg px-4 py-2 text-xs font-bold uppercase ${screen === "accounts" ? "bg-white/[.09] text-white" : "text-slate-500"}`}>Accounts</button></nav></header>{message && <div className={`mb-5 rounded-xl border px-4 py-3 text-xs ${/error|failed|cannot|melebihi|tidak|invalid|insufficient|negative/i.test(message) ? "border-red-400/20 bg-red-400/[.05] text-red-300" : "border-emerald-400/20 bg-emerald-400/[.05] text-emerald-300"}`}>{message}</div>}
    {screen === "overview" && <div className="space-y-5"><div className="grid gap-3 md:grid-cols-4">{[["Total Investment",data?.summary.totalInvestmentValue ?? 0,"portfolio + cash"],["RDN Cash",data?.summary.totalCash ?? 0,"all settlement balances"],["Portfolio",data?.summary.totalValue ?? 0,"current market value"],["Unrealized P/L",data?.summary.unrealized ?? 0,`${Number(data?.summary.returnPct ?? 0).toFixed(2)}% return`]].map(([l,v,s]) => <div className={card} key={String(l)}><p className="text-[10px] uppercase tracking-widest text-slate-500">{l}</p><p className="mt-2 text-xl font-bold text-white">{money(v as number)}</p><p className="mt-1 text-[10px] text-slate-600">{s}</p></div>)}</div><section className={card}><div className="mb-4 flex items-center justify-between"><div><h2 className="font-semibold text-white">Investment Accounts</h2><p className="text-xs text-slate-600">Klik account langsung membuka Transactions.</p></div><button type="button" onClick={() => openAccountEditor()} className="rounded-lg bg-emerald-400 px-3 py-2 text-xs font-bold text-[#07110b]">+ Add account</button></div>{activeAccounts.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{activeAccounts.map(a => { const f = feeInfo(a); const portfolio = holdings.filter(h => h.account.id === a.id).reduce((s, h) => s + Number(h.marketValue), 0); return <button type="button" key={a.id} onClick={() => chooseAccount(a.id, "transactions")} className="rounded-2xl border border-white/10 bg-white/[.02] p-5 text-left transition hover:border-emerald-400/30"><div className="flex items-start justify-between"><div><p className="text-base font-semibold text-white">{a.provider.name}</p><p className="mt-1 text-xs text-slate-500">{f.rdnBankName ? `RDN ${f.rdnBankName}` : "RDN"} · {a.currency.code}</p></div><span className="text-[10px] font-bold uppercase tracking-widest text-emerald-300">Open →</span></div><div className="mt-5 grid grid-cols-2 gap-3 text-xs"><div><p className="text-slate-600">RDN Cash</p><p className="mt-1 font-semibold text-white">{money(a.cashAccount?.balance ?? 0, a.currency.code)}</p></div><div><p className="text-slate-600">Portfolio</p><p className="mt-1 font-semibold text-white">{money(portfolio, a.currency.code)}</p></div></div></button>; })}</div> : <div className="rounded-xl border border-dashed border-white/10 p-8 text-center text-xs text-slate-600">Belum ada investment account.</div>}</section></div>}

    {screen === "transactions" && selected && <div className="space-y-5"><section className={card}><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">{selected.provider.name}</p><h2 className="mt-1 text-xl font-semibold text-white">{selected.name}</h2><p className="mt-1 text-xs text-slate-500">{fee.rdnBankName ? `RDN ${fee.rdnBankName}` : "RDN"} · {selected.currency.code}</p></div><div className="flex items-center gap-2"><label className="hidden text-xs text-slate-500 sm:block">Account</label><select className="${select}" value={accountId} onChange={e => { setAccountId(e.target.value); setSelectedAssetId(""); }}>{activeAccounts.map(a => <option key={a.id} value={a.id}>{a.provider.name} · {feeInfo(a).rdnBankName || "RDN"}</option>)}</select></div></div></section>
      <section className={card}><div className="mb-4 flex items-center justify-between"><div><h2 className="text-lg font-semibold text-white">Asset Summary</h2><p className="text-xs text-slate-600">Gabungan seluruh purchase lot yang masih dimiliki.</p></div><button type="button" onClick={() => openTrade("BUY")} className="rounded-lg bg-emerald-400 px-3 py-2 text-xs font-bold text-[#07110b]">+ New transaction</button></div>{assetSummaries.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{assetSummaries.map(s => <button key={s.asset.id} type="button" onClick={() => setSelectedAssetId(selectedAssetId === s.asset.id ? "" : s.asset.id)} className={`rounded-2xl border p-4 text-left transition ${selectedAssetId === s.asset.id ? "border-emerald-400/40 bg-emerald-400/[.04]" : "border-white/10 bg-white/[.02] hover:border-white/20"}`}><div className="flex items-start justify-between"><div><p className="text-lg font-bold text-white">{s.asset.symbol || s.asset.name}</p><p className="text-[10px] text-slate-600">{s.asset.name}</p></div><span className="text-xs text-slate-500">{nf(s.quantity / unitsPerLot(s.asset), 0)} lot</span></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div><p className="text-slate-600">Avg Cost</p><p className="mt-1 font-semibold text-white">{money(s.avgCost, selected.currency.code)}</p></div><div><p className="text-slate-600">Current</p><p className="mt-1 font-semibold text-white">{s.currentPrice == null ? "—" : money(s.currentPrice, selected.currency.code)}</p></div><div><p className="text-slate-600">Value</p><p className="mt-1 font-semibold text-white">{money(s.marketValue, selected.currency.code)}</p></div><div><p className="text-slate-600">Min. Sell</p><p className="mt-1 font-semibold text-amber-300">{money(s.minSell, selected.currency.code)}</p></div></div><div className="mt-3 flex items-center justify-between border-t border-white/5 pt-3"><span className="text-[10px] uppercase tracking-widest text-slate-600">Unrealized P/L</span><span className={`text-sm font-bold ${s.pnl >= 0 ? "text-emerald-300" : "text-red-300"}`}>{money(s.pnl, selected.currency.code)}</span></div><div className="mt-3 flex justify-end"><button type="button" onClick={e => { e.stopPropagation(); setSellAllAssetId(s.asset.id); setSellAllPrice(String(s.currentPrice ?? s.minSell)); setShowSellAll(true); }} className="rounded-lg border border-emerald-400/20 px-3 py-1.5 text-[10px] font-bold uppercase tracking-wide text-emerald-300">Sell All</button></div></button>)}</div> : <div className="rounded-xl border border-dashed border-white/10 p-8 text-center text-xs text-slate-600">Belum ada open position.</div>}</section>
      <section className={card}><div className="mb-4 flex items-center justify-between"><div><h2 className="text-lg font-semibold text-white">Transaction Detail{selectedAssetId ? ` · ${assetSummaries.find(a => a.asset.id === selectedAssetId)?.asset.symbol || "Asset"}` : ""}</h2><p className="text-xs text-slate-600">Open positions selalu ditampilkan paling atas.</p></div>{selectedAssetId && <button type="button" onClick={() => setSelectedAssetId("")} className="text-xs text-slate-400 hover:text-white">Clear filter</button>}</div><div className="mb-5 rounded-xl border border-emerald-400/10 bg-emerald-400/[.02] p-3 text-xs text-slate-500">OPEN POSITIONS · {selectedAssetRows.length} lot rows</div>{selectedAssetRows.length ? <div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="px-3 py-3">Date</th><th>Asset</th><th>Buy</th><th>Remaining</th><th>Current</th><th>Min. Sell</th><th>P/L</th><th className="text-right">Action</th></tr></thead><tbody className="divide-y divide-white/5">{selectedAssetRows.map(r => <tr key={r.lotId}><td className="px-3 py-3 text-slate-400">{new Date(r.transactionDate).toLocaleDateString("id-ID")}</td><td><span className="font-semibold text-white">{r.asset.symbol || r.asset.name}</span><span className="block text-[10px] text-slate-600">{r.asset.name}</span></td><td>{money(r.unitPrice, selected.currency.code)}</td><td>{nf(Number(r.remainingQuantity) / unitsPerLot(r.asset), 0)} lot</td><td>{r.currentPrice == null ? "—" : money(r.currentPrice, selected.currency.code)}</td><td className="text-amber-300">{money(r.minimumSellPrice, selected.currency.code)}</td><td className={Number(r.unrealizedGainLoss) >= 0 ? "text-emerald-300" : "text-red-300"}>{money(r.unrealizedGainLoss, selected.currency.code)}</td><td className="text-right"><button type="button" onClick={() => openTrade("SELL", r)} className="rounded-lg bg-emerald-400 px-3 py-1.5 text-[10px] font-bold text-[#07110b]">Sell / Split</button><button type="button" onClick={() => deleteTransaction(r.id)} className="ml-2 rounded-lg border border-red-400/20 px-3 py-1.5 text-[10px] font-bold text-red-300">Delete</button></td></tr>)}</tbody></table></div> : <div className="p-8 text-center text-xs text-slate-600">Tidak ada open position untuk filter ini.</div>}<div className="mt-6 rounded-xl border border-white/10 bg-white/[.02] p-3 text-xs text-slate-500">CLOSED TRANSACTIONS · {selectedClosed.length}</div>{selectedClosed.length > 0 && <div className="mt-2 overflow-x-auto"><table className="w-full min-w-[900px] text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="px-3 py-3">Date</th><th>Asset</th><th>Sold</th><th>Price</th><th>Net proceeds</th><th>Realized P/L</th><th className="text-right">Status</th></tr></thead><tbody className="divide-y divide-white/5">{selectedClosed.map(x => <tr key={x.sale.id}><td className="px-3 py-3 text-slate-400">{new Date(x.sale.date).toLocaleDateString("id-ID")}</td><td><span className="font-semibold text-white">{x.lot.asset.symbol || x.lot.asset.name}</span><span className="block text-[10px] text-slate-600">Buy {money(x.lot.unitPrice, selected.currency.code)}</span></td><td>{nf(Number(x.sale.quantity) / unitsPerLot(x.lot.asset), 0)} lot</td><td>{money(x.sale.price, selected.currency.code)}</td><td>{money(x.sale.proceeds, selected.currency.code)}</td><td className={Number(x.sale.realized) >= 0 ? "text-emerald-300" : "text-red-300"}>{money(x.sale.realized, selected.currency.code)}</td><td className="text-right text-slate-500">SOLD</td></tr>)}</tbody></table></div>}</section>
      </div>}

    {screen === "accounts" && <div className="space-y-5"><section className={card}><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold text-white">Investment Accounts</h2><p className="text-xs text-slate-600">Kelola broker, RDN, fee dan lifecycle account.</p></div><button type="button" onClick={() => openAccountEditor()} className="rounded-lg bg-emerald-400 px-3 py-2 text-xs font-bold text-[#07110b]">+ Add account</button></div>{activeAccounts.length ? <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{activeAccounts.map(a => { const f = feeInfo(a); return <button type="button" key={a.id} onClick={() => setAccountId(accountId === a.id ? "" : a.id)} className={`rounded-2xl border p-4 text-left ${accountId === a.id ? "border-emerald-400/40 bg-emerald-400/[.04]" : "border-white/10 bg-white/[.02]"}`}><div className="flex items-start justify-between"><div><p className="font-semibold text-white">{a.provider.name}</p><p className="mt-1 text-[10px] text-slate-500">{f.rdnBankName ? `RDN ${f.rdnBankName}` : "RDN"} · {a.currency.code}</p></div><span className="text-[10px] uppercase tracking-widest text-emerald-300">{a.isActive === false ? "Closed" : "Active"}</span></div><div className="mt-4"><p className="text-[10px] text-slate-600">RDN Balance</p><p className="mt-1 text-xl font-bold text-white">{money(a.cashAccount?.balance ?? 0, a.currency.code)}</p></div></button>; })}</div> : <div className="mt-4 rounded-xl border border-dashed border-white/10 p-8 text-center text-xs text-slate-600">Belum ada investment account.</div>}</section>{selected && <section className={card}><div className="flex items-start justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">Account Detail</p><h2 className="mt-1 text-xl font-semibold text-white">{selected.provider.name}</h2><p className="mt-1 text-xs text-slate-500">{fee.rdnBankName ? `RDN ${fee.rdnBankName}` : "RDN"} · {fee.rdnAccountNumber || "No. RDN"} · {selected.currency.code}</p></div><div className="flex gap-2"><button type="button" onClick={() => openAccountEditor(selected)} className="rounded-lg border border-white/10 px-3 py-2 text-xs text-slate-300">Edit</button><button type="button" onClick={() => accountAction("account.close", selected)} className="rounded-lg border border-amber-400/20 px-3 py-2 text-xs text-amber-300">Close</button><button type="button" onClick={() => accountAction("account.delete", selected)} className="rounded-lg border border-red-400/20 px-3 py-2 text-xs text-red-300">Delete</button></div></div><div className="mt-5 grid gap-3 md:grid-cols-3"><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] text-slate-600">RDN balance</p><p className="mt-1 text-lg font-bold text-white">{money(selectedCash?.balance ?? 0, selected.currency.code)}</p></div><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] text-slate-600">Buy fee</p><p className="mt-1 text-lg font-bold text-white">{nf(fee.buyFeePct, 3)}%</p></div><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] text-slate-600">Sell fee</p><p className="mt-1 text-lg font-bold text-white">{nf(fee.sellFeePct, 3)}%</p></div></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><div className="rounded-2xl border border-white/10 bg-white/[.02] p-4"><div className="flex items-center justify-between"><div><h3 className="font-semibold text-white">Update RDN Balance</h3><p className="text-xs text-slate-600">Set sesuai saldo aktual broker.</p></div></div><div className="mt-4 space-y-3"><input className={input} type="number" min="0" step="0.01" placeholder="Actual balance" value={cashBalance} onChange={e => setCashBalance(e.target.value)} /><input className={input} type="date" value={cashDate} onChange={e => setCashDate(e.target.value)} /><button type="button" onClick={saveCash} disabled={!selectedCash || !cashBalance || busy} className="rounded-xl bg-emerald-400 px-4 py-2.5 text-sm font-bold text-[#07110b] disabled:opacity-40">Update balance</button></div></div><div className="rounded-2xl border border-white/10 bg-white/[.02] p-4"><div><h3 className="font-semibold text-white">Withdraw to Wallet</h3><p className="text-xs text-slate-600">Pindahkan dana dari RDN ke Wallet OKANE.</p></div><div className="mt-4 space-y-3"><select className={select} value={withdrawWalletId} onChange={e => setWithdrawWalletId(e.target.value)}><option value="">Select wallet</option>{withdrawWallets.filter(w => w.currency.code === selected.currency.code).map(w => <option key={w.id} value={w.id}>{w.name} · {money(w.balance,w.currency.code)}</option>)}</select><input className={input} type="number" min="0.01" step="0.01" max={String(selectedCash?.balance ?? 0)} placeholder="Amount" value={withdrawAmount} onChange={e => setWithdrawAmount(e.target.value)} /><button type="button" onClick={withdraw} disabled={busy || !selectedCash || !withdrawWalletId || Number(withdrawAmount) <= 0 || Number(withdrawAmount) > Number(selectedCash?.balance ?? 0)} className="rounded-xl bg-emerald-400 px-4 py-2.5 text-sm font-bold text-[#07110b] disabled:opacity-40">Withdraw to Wallet</button></div></div></div><div className="mt-5"><div className="flex items-center justify-between"><div><h3 className="font-semibold text-white">RDN Transaction History</h3><p className="text-xs text-slate-600">History hanya untuk RDN account yang dipilih.</p></div><button type="button" onClick={() => { setHistoryOpen(!historyOpen); if (!historyOpen && selectedCash) loadHistory(selectedCash.id); }} className="text-xs text-slate-400">{historyOpen ? "Hide" : "Show"}</button></div>{historyOpen && <div className="mt-3 overflow-x-auto rounded-xl border border-white/10"><table className="w-full min-w-[760px] text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="px-4 py-3">Date</th><th>Type</th><th>Description</th><th className="text-right">Debit</th><th className="text-right">Credit</th><th className="px-4 text-right">Balance</th></tr></thead><tbody className="divide-y divide-white/5">{historyLoading ? <tr><td className="px-4 py-6 text-center text-slate-600" colSpan={6}>Loading…</td></tr> : historyRows.map(x => <tr key={x.id}><td className="px-4 py-3 text-slate-400">{new Date(x.date).toLocaleDateString("id-ID")}</td><td>{x.movementType}</td><td>{x.description}</td><td className="text-right text-red-300">{Number(x.debit) ? money(x.debit, selected.currency.code) : "—"}</td><td className="text-right text-emerald-300">{Number(x.credit) ? money(x.credit, selected.currency.code) : "—"}</td><td className="px-4 text-right font-semibold text-white">{money(x.balance, selected.currency.code)}</td></tr>)}</tbody></table></div>}</div></section>}</div>}

    {!data && <div className="rounded-xl border border-white/10 bg-white/[.02] p-8 text-center text-sm text-slate-500">Loading Investments…</div>}

    <AccountModal open={showAccountModal} editing={editing} form={accountForm} currencies={currencies} onClose={() => setShowAccountModal(false)} onChange={setAccountForm} onSubmit={saveAccount} busy={busy} />
    {selected && <TradeModal open={showTrade} trade={trade} assets={pickerAssets} account={selected} ledger={ledger} onClose={() => setShowTrade(false)} onChange={setTrade} onSubmit={submitTrade} busy={busy} />}
    <SellAllModal open={showSellAll} summary={assetSummaries.find(a => a.asset.id === sellAllAssetId) ?? null} account={selected} price={sellAllPrice} setPrice={setSellAllPrice} onClose={() => setShowSellAll(false)} onSubmit={sellAll} busy={busy} />
  </div>;
}
